"""Replay specs/goldens/navigation.json, generated by the R package.

Tables are compared as sets of rows (R sorts in the session locale). Vectors
whose order is canonical (units, children, parents) are compared in order.
"""
import pyarrow as pa
import pytest
from conftest import build_scale, load_golden, rowset

import nestedscales as ns

CASES = load_golden("navigation.json")


def build(c):
    return build_scale(c["construct"])


@pytest.fixture(params=sorted(CASES), scope="module")
def case(request):
    c = CASES[request.param]
    return build(c), c


def test_accessors(case):
    s, c = case
    assert ns.scale_frames(s) == c["frames"]
    assert ns.scale_key(s) == c["key"]
    assert ns.scale_atom_level(s) == c["atom_level"]
    assert ns.scale_weights(s) == c["weights"]
    assert ns.scale_coverage(s) == pytest.approx(c["coverage"] or {})
    for f, r in c["rank"].items():
        assert ns.scale_rank(s, f) == r
    for f, u in c["units"].items():
        assert ns.scale_units(s, f) == u


def test_family_and_ancestry(case):
    s, c = case
    assert rowset(ns.scale_family(s)) == rowset(c["family"])
    assert rowset(ns.scale_ancestry(s)) == rowset(c["ancestry"])


def test_nests_and_crosses(case):
    s, c = case
    for g in c["nests"]:
        v = ns.scale_nests(s, g["parent"], g["child"])
        assert v.ok == g["ok"], g
        assert set(v.offenders) == set(g["offenders"]), g
    for g in c["crosses"]:
        v = ns.scale_crosses(s, g["a"], g["b"])
        assert v.ok == g["ok"], g
        assert set(v.offenders) == set(g["offenders"]), g


def test_is_uniform(case):
    s, c = case
    for g in c["uniform"]:
        v = ns.scale_is_uniform(s, g["frame"], weight=g["weight"])
        assert v.ok == g["ok"], g
        if g["sizes"] is None:
            assert v.sizes is None
        else:
            assert v.sizes == pytest.approx(g["sizes"])


def test_navigation(case):
    s, c = case
    for g in c["nav"]:
        fn = getattr(ns, g["fn"])
        if g["error"]:
            with pytest.raises(ns.NestedScalesError):
                fn(s, g["frame"], g["unit"])
            continue
        got = fn(s, g["frame"], g["unit"])
        if isinstance(got, pa.Table):
            assert got.to_pylist() == g["value"], g
        else:
            assert got == g["value"], g
